quotes=[('旅行日记 · 北京.mp4','到了<mark>北京</mark>以后，我们决定先去看看这座城市。','00:12 – 00:15 · 余弦 0.920',False),('周末随拍.mp4','下一站是<mark>北京</mark>，然后再一路向北。','02:04 – 02:08 · 余弦 0.810',False),('城市访谈.mp4','这座城市的变化，让我们想起第一次来的时候。','00:42 – 00:46 · 余弦 0.752',True)]
def cards(low=False):
 out=''
 for i,(name,q,meta,warn) in enumerate(quotes):
  if low:
   q=['明年的旅行计划还没有确定。','我们聊了聊不同城市的生活方式。','出发之前，需要做一些准备。'][i]
   meta=['00:28 – 00:32 · 余弦 0.672','01:16 – 01:20 · 余弦 0.631','00:08 – 00:12 · 余弦 0.588'][i];warn=True
  out+=f'<div class="card"><div class="thumb">{land}</div><div class="copy"><div class="title">{name}</div><div class="quote">{q}</div><div class="meta">{meta}</div>'+('<span class="warn">可能不准确</span>' if warn else '')+'</div></div>'
 return out
